using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;
namespace Tikal.Tests.Editor {
public static class PlazaKeynesForest {
 const string Dir=PlazaKeynesAuthoring.Art+"/Forest";static string[] Names={"PFB_VEG_CeibaTropical_01","PFB_VEG_ArbolTropical_02","PFB_VEG_ArbolTropical_03","PFB_VEG_ArbustoTropical_02"};
 [Serializable]public class BakeInfo{public string[] sourcePrefabs;public string atlas,material;public int impostorClusters,sectors,triangles;public bool colliders,shadows;public Vector3[] sourceDimensions;}
 static GameObject Source(string n){var paths=AssetDatabase.FindAssets(n+" t:Prefab",new[]{"Assets/_Project/Prefabs/Environment"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>Path.GetFileNameWithoutExtension(p)==n).ToArray();if(paths.Length!=1)throw new Exception("Exact forest source "+n);return AssetDatabase.LoadAssetAtPath<GameObject>(paths[0]);}
 public static void Build(Transform parent){Directory.CreateDirectory(Dir);AssetDatabase.Refresh();var models=Names.Select(Source).ToArray();var sizes=models.Select(m=>PlazaKeynesAuthoring.BoundsOf(m).size).ToArray();string imagePath=Dir+"/T_PlazaKeynes_ForestAtlas.png";if(!File.Exists(imagePath)){int cell=512;var atlas=new Texture2D(cell*2,cell*2,TextureFormat.RGBA32,false);for(int i=0;i<4;i++){
 var clone=(GameObject)PrefabUtility.InstantiatePrefab(models[i]);clone.transform.position=new Vector3(0,500,0);foreach(var t in clone.GetComponentsInChildren<Transform>(true))t.gameObject.layer=29;foreach(var c in clone.GetComponentsInChildren<Collider>(true))c.enabled=false;foreach(var r in clone.GetComponentsInChildren<Renderer>(true))r.shadowCastingMode=ShadowCastingMode.Off;foreach(var g in clone.GetComponentsInChildren<LODGroup>())g.ForceLOD(g.lodCount-1);var bounds=PlazaKeynesAuthoring.BoundsOf(clone);var camera=new GameObject("Temporary_ForestAtlas_Camera").AddComponent<Camera>();var data=camera.gameObject.AddComponent<UniversalAdditionalCameraData>();data.renderPostProcessing=false;camera.enabled=false;camera.cullingMask=1<<29;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(0,0,0,0);camera.orthographic=true;camera.orthographicSize=Mathf.Max(bounds.size.x,bounds.size.y)*.55f;camera.nearClipPlane=.01f;camera.farClipPlane=200;camera.transform.position=bounds.center+Vector3.back*70;camera.transform.LookAt(bounds.center);var rt=new RenderTexture(cell,cell,24,RenderTextureFormat.ARGB32);rt.Create();var tex=new Texture2D(cell,cell,TextureFormat.RGBA32,false);var prev=RenderTexture.active;try{var req=new UniversalRenderPipeline.SingleCameraRequest{destination=rt};RenderPipeline.SubmitRenderRequest(camera,req);RenderPipeline.SubmitRenderRequest(camera,req);RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,cell,cell),0,0);tex.Apply();atlas.SetPixels((i%2)*cell,(i/2)*cell,cell,cell,tex.GetPixels());}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(camera.gameObject);UnityEngine.Object.DestroyImmediate(clone);}}
 atlas.Apply();File.WriteAllBytes(imagePath,atlas.EncodeToPNG());UnityEngine.Object.DestroyImmediate(atlas);AssetDatabase.ImportAsset(imagePath,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(imagePath);importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=true;importer.sRGBTexture=true;importer.mipmapEnabled=true;importer.maxTextureSize=1024;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.SaveAndReimport();}
 string matPath=Dir+"/MAT_PlazaKeynes_ForestImpostor.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!material){material=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="MAT_PlazaKeynes_ForestImpostor",enableInstancing=true};var image=AssetDatabase.LoadAssetAtPath<Texture2D>(imagePath);material.SetTexture("_BaseMap",image);material.SetColor("_BaseColor",new Color(.9f,.95f,.9f));material.SetFloat("_Surface",0);material.SetFloat("_AlphaClip",1);material.SetFloat("_Cutoff",.3f);material.SetFloat("_Cull",0);material.SetFloat("_Metallic",0);material.SetFloat("_Smoothness",0);material.SetFloat("_SpecularHighlights",0);material.SetFloat("_EnvironmentReflections",0);material.SetFloat("_ReceiveShadows",0);material.EnableKeyword("_ALPHATEST_ON");AssetDatabase.CreateAsset(material,matPath);}
 var random=new System.Random(241027);var vs=Enumerable.Range(0,8).Select(i=>new List<Vector3>()).ToArray();var uvs=Enumerable.Range(0,8).Select(i=>new List<Vector2>()).ToArray();var ts=Enumerable.Range(0,8).Select(i=>new List<int>()).ToArray();int clusters=0;
 for(int i=0;i<640;i++){float angle=i*2.399963f,radius=150+155*Mathf.Sqrt((i+.5f)/640);float x=Mathf.Sin(angle)*radius,z=Mathf.Cos(angle)*radius;if(new[]{new Vector2(-120,165),new Vector2(140,195),new Vector2(30,250)}.Any(p=>Vector2.Distance(p,new Vector2(x,z))<27))continue;int slot=i%4,sector=((int)(Mathf.Repeat(angle,Mathf.PI*2)/(Mathf.PI*2)*8))%8;float height=slot==3?4+(float)random.NextDouble()*3:15+(float)random.NextDouble()*9;float ratio=sizes[slot].x/Mathf.Max(sizes[slot].y,.1f);float width=height;var center=new Vector3(x,PlazaKeynesAuthoring.Height(x,z)-.6f,z);float yaw=(float)random.NextDouble()*180;for(int plane=0;plane<2;plane++){var right=Quaternion.Euler(0,yaw+plane*90,0)*Vector3.right*(width*.5f);int n=vs[sector].Count;vs[sector].AddRange(new[]{center-right,center+right,center+right+Vector3.up*height,center-right+Vector3.up*height});float u=slot%2*.5f,v=slot/2*.5f,eps=.001f;uvs[sector].AddRange(new[]{new Vector2(u+eps,v+eps),new Vector2(u+.5f-eps,v+eps),new Vector2(u+.5f-eps,v+.5f-eps),new Vector2(u+eps,v+.5f-eps)});ts[sector].AddRange(new[]{n,n+2,n+1,n,n+3,n+2});}clusters++;}
 for(int s=0;s<8;s++){string meshPath=Dir+"/SM_Forest_Sector_"+s+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(!mesh){mesh=new Mesh{name="SM_Forest_Sector_"+s};mesh.SetVertices(vs[s]);mesh.SetUVs(0,uvs[s]);mesh.SetTriangles(ts[s],0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,meshPath);}var g=new GameObject("ForestImpostor_Sector_"+s);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;renderer.lightProbeUsage=LightProbeUsage.Off;renderer.reflectionProbeUsage=ReflectionProbeUsage.Off;g.isStatic=true;}
 File.WriteAllText(PlazaKeynesAuthoring.Evidence+"/Forest_Impostor_Audit.json",JsonUtility.ToJson(new BakeInfo{sourcePrefabs=models.Select(AssetDatabase.GetAssetPath).ToArray(),sourceDimensions=sizes,atlas=imagePath,material=matPath,impostorClusters=clusters,sectors=8,triangles=clusters*4,colliders=false,shadows=false},true));}
}
